public class SuperFieldBoundary17 {
 public virtual class Box { public String label; public Box(String label){this.label=label;} }
 public class FancyBox extends Box { public FancyBox(String label){super(label);} }
 public virtual class Base {
  protected Box state;
  public String readBase(){return state==null?'null':state.label;}
 }
 public virtual class Child extends Base {
  private FancyBox state;
  public Child(){super.state=new Box('base');this.state=new FancyBox('child');}
  public String readChild(){return state==null?'null':state.label;}
  public String readSuper(){return super.state==null?'null':super.state.label;}
  public void rewrite(){super.state=new Box('changed');}
 }
 public class Grand extends Child { public Grand(){super();} }
 public virtual class SameChild extends Base {
  private Box state;
  public SameChild(){super.state=new Box('same-base');this.state=new Box('same-child');}
  public String readChild(){return state==null?'null':state.label;}
  public String readSuper(){return super.state==null?'null':super.state.label;}
 }
 public class SharedChild extends Base {
  protected FancyBox state;
  public SharedChild(){super.state=new Box('shared-base');this.state=new FancyBox('shared-child');}
  public String readChild(){return state==null?'null':state.label;}
 }
 public static List<String> capture(){
  List<String> out=new List<String>();
  Child a=new Child();out.add(a.readBase());out.add(a.readChild());out.add(a.readSuper());a.rewrite();out.add(a.readBase());out.add(a.readChild());
  Grand b=new Grand();out.add(b.readBase());out.add(b.readChild());out.add(b.readSuper());b.rewrite();out.add(b.readBase());out.add(b.readChild());
  SameChild c=new SameChild();out.add(c.readBase());out.add(c.readChild());out.add(c.readSuper());
  SharedChild d=new SharedChild();out.add(d.readBase());out.add(d.readChild());
  BoundaryPrivate17 top=new BoundaryPrivate17();out.add(top.readBase());out.add(top.readChild());out.add(top.readSuper());top.rewrite();out.add(top.readBase());out.add(top.readChild());
  BoundaryGrand17 grand=new BoundaryGrand17();out.add(grand.readBase());out.add(grand.readChild());out.add(grand.readSuper());
  BoundaryShared17 shared=new BoundaryShared17(true);out.add(shared.readBase());out.add(shared.readChild());out.add(shared.readSuper());
  BoundaryShared17 only=new BoundaryShared17(false);out.add(only.readBase());out.add(only.readChild());out.add(only.readSuper());
  return out;
 }
}

